import re
import pytesseract
from PIL import Image
from openpyxl import Workbook

IMG_DIR = "/app/workspace/dataset/img"
OUT = "/app/workspace/stat_ocr.xlsx"


def ocr(path):
    img = Image.open(path)
    w, h = img.size
    if max(w, h) < 1600:
        img = img.resize((w * 2, h * 2), Image.LANCZOS)
    return pytesseract.image_to_string(img)


def parse_date(text):
    up = text.upper()
    month_map = {
        'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
        'JUL': 7, 'AUG': 8, 'SEP': 9, 'SEPT': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12,
    }

    def valid(d, mo, y):
        if y < 100:
            y = 2000 + y
        if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2030:
            return f"{y:04d}-{mo:02d}-{d:02d}"
        return None

    # DD Mon YYYY
    for m in re.finditer(r'\b(\d{1,2})[\s\-/]+([A-Z]{3,4})[\s\-/]+(\d{2,4})\b', up):
        d = int(m.group(1))
        mon = m.group(2)
        if mon in month_map:
            y = int(m.group(3))
            r = valid(d, month_map[mon], y)
            if r:
                return r

    # DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY
    for m in re.finditer(r'\b(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})\b', up):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        r = valid(d, mo, y)
        if r:
            return r

    # YYYY-MM-DD or YYYY/MM/DD
    for m in re.finditer(r'\b(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})\b', up):
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        r = valid(d, mo, y)
        if r:
            return r

    # DD/MM/YY, DD-MM-YY
    for m in re.finditer(r'\b(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})\b', up):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        r = valid(d, mo, y)
        if r:
            return r

    # 8-digit run like DDMMYYYY (fallback for OCR losing separators, e.g. "2032018")
    for m in re.finditer(r'\b(\d{1,2})(\d{2})(\d{4})\b', up):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        r = valid(d, mo, y)
        if r:
            return r

    return None


AMOUNT_RE = re.compile(r'(\d{1,3}(?:,\d{3})*|\d+)\s*\.\s*(\d{2})(?!\d)')


def extract_amount(line):
    matches = AMOUNT_RE.findall(line)
    if matches:
        intp, dec = matches[-1]
        return f"{int(intp.replace(',', ''))}.{dec}"
    return None


EXCLUSION_RE = re.compile(
    r'\bSUB\s*-?\s*TOTAL\b|\bSUBTOTAL\b|\bDISCOUNT\b|\bCASH\s+TENDER'
)
STRONG_EXCL_START = re.compile(r'^(TAX|GST|SST|CHANGE)\b')
TAX_LABEL_RE = re.compile(
    r'\bTAX\s+(AMT|AMOUNT|TOTAL|TOTALS|CODE|RATE|SUMMARY)\b'
    r'|\bGST\s+(AMT|AMOUNT|SUMMARY|TOTAL|CODE|RATE|@|\d)'
    r'|\bTAX\s+INVOICE\b'
)

CUTOFF_RE = re.compile(
    r'\bCASH\b|\bCHANGE\b|\bVISA\b|\bMASTERCARD\b|\bMASTER\s*CARD\b|\bDEBIT\b|\bCREDIT\b'
    r'|\bPAYMENT\b|\bTENDERED\b|\bAMEX\b|\bAMOUNT\s+PAID\b'
)

TIER1 = re.compile(r'GRAND\s*TOTA')
TIER2 = re.compile(r'\bTOTAL\b[^A-Z\n]{0,3}\bRM\b')
TIER3 = re.compile(r'\bTOTAL\s+AMOUNT\b')
TIER4_PATTERNS = [
    re.compile(r'\bNETT?\s+TOTAL\b'),
    re.compile(r'\bTOTAL\s+DUE\b'),
    re.compile(r'\bAMOUNT\s+DUE\b'),
    re.compile(r'\bBALANCE\s+DUE\b'),
    re.compile(r'\bTOTAL\b'),
    re.compile(r'\bAMOUNT\b'),
]


def is_excluded(up_line):
    if EXCLUSION_RE.search(up_line):
        return True
    stripped = re.sub(r'^[^A-Z]*', '', up_line)
    if STRONG_EXCL_START.match(stripped):
        return True
    if TAX_LABEL_RE.search(up_line):
        return True
    return False


def find_cutoff(upper_lines):
    for i, l in enumerate(upper_lines):
        if CUTOFF_RE.search(l):
            return i
    return len(upper_lines)


def extract_total(text):
    lines = text.split('\n')
    upper_lines = [l.upper() for l in lines]
    cutoff = find_cutoff(upper_lines)

    def scan(pattern_check):
        found = None
        for i in range(cutoff):
            up = upper_lines[i]
            if is_excluded(up):
                continue
            if pattern_check(up):
                amt = extract_amount(lines[i])
                if amt is None and i + 1 < len(lines):
                    amt = extract_amount(lines[i + 1])
                if amt:
                    found = amt
        return found

    # Tier 1
    r = scan(lambda up: bool(TIER1.search(up)))
    if r:
        return r
    # Tier 2
    r = scan(lambda up: bool(TIER2.search(up)))
    if r:
        return r
    # Tier 3
    r = scan(lambda up: bool(TIER3.search(up)))
    if r:
        return r
    # Tier 4
    for pat in TIER4_PATTERNS:
        r = scan(lambda up, _p=pat: bool(_p.search(up)))
        if r:
            return r
    return None


def main():
    files = sorted(f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png')))
    rows = []
    for f in files:
        text = ocr(os.path.join(IMG_DIR, f))
        date = parse_date(text)
        total = extract_total(text)
        rows.append((f, date, total))
        print(f, date, total)

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for r in rows:
        ws.append(list(r))
    wb.save(OUT)


if __name__ == "__main__":
    main()
