import re
import pytesseract
from PIL import Image
from openpyxl import Workbook

IMG_DIR = "/app/workspace/dataset/img"
OUT = "/app/workspace/stat_ocr.xlsx"


def ocr_variants(path):
    img = Image.open(path).convert('L')
    w, h = img.size
    variants = []
    for scale in (2, 3):
        scaled = img.resize((w * scale, h * scale), Image.LANCZOS)
        for psm in ('4', '6', '3'):
            variants.append(pytesseract.image_to_string(scaled, config=f'--psm {psm}'))
    return variants


MONTH_MAP = {
    'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
    'JUL': 7, 'AUG': 8, 'SEP': 9, 'SEPT': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12,
}


def _valid_date(d, mo, y):
    if y < 100:
        y = 2000 + y
    if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2030:
        return f"{y:04d}-{mo:02d}-{d:02d}"
    return None


def parse_date(text):
    up = text.upper()

    for m in re.finditer(r'\b(\d{1,2})[\s\-/]+([A-Z]{3,4})[\s\-/]+(\d{2,4})\b', up):
        mon = m.group(2)
        if mon in MONTH_MAP:
            r = _valid_date(int(m.group(1)), MONTH_MAP[mon], int(m.group(3)))
            if r:
                return r

    for m in re.finditer(r'(?<!\d)(\d{1,2})\s*[/\-.]\s*(\d{1,2})\s*[/\-.]\s*(\d{4})(?!\d)', up):
        r = _valid_date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        if r:
            return r

    for m in re.finditer(r'(?<!\d)(\d{4})\s*[/\-.]\s*(\d{1,2})\s*[/\-.]\s*(\d{1,2})(?!\d)', up):
        r = _valid_date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
        if r:
            return r

    for m in re.finditer(r'(?<!\d)(\d{1,2})\s*[/\-.]\s*(\d{1,2})\s*[/\-.]\s*(\d{2})(?!\d)', up):
        r = _valid_date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        if r:
            return r

    return None


AMOUNT_RE = re.compile(r'(?<!\d)(\d{1,3}(?:,\d{3})*|\d+)\s*\.\s*(\d{2})(?!\d)')
COMMA_DECIMAL_RE = re.compile(r'(?<!\d)(\d+),(\d{2})(?!\d)')
LOOSE_AMOUNT_RE = re.compile(r'(?<!\d)(\d{1,3}(?:,\d{3})*|\d+)\s{1,3}(\d{2})(?!\d)')


def normalize_line(line):
    return COMMA_DECIMAL_RE.sub(r'\1.\2', line)


def extract_amount(line, loose=False, int_fallback=False):
    line = normalize_line(line)
    matches = AMOUNT_RE.findall(line)
    if matches:
        intp, dec = matches[-1]
        return f"{int(intp.replace(',', ''))}.{dec}"
    if loose:
        matches = LOOSE_AMOUNT_RE.findall(line)
        if matches:
            intp, dec = matches[-1]
            return f"{int(intp.replace(',', ''))}.{dec}"
    if int_fallback:
        m = re.findall(r'(?<!\d)(\d{4,})(?!\d)', line)
        if m:
            v = m[-1]
            return f"{int(v[:-2])}.{v[-2:]}"
    return None


EXCLUSION_RE = re.compile(
    r'\bSUB\s*-?\s*TOTAL\b|\bSUBTOTAL\b|\bDISCOUNT\b|\bCASH\s+TENDER'
)
STRONG_EXCL_START = re.compile(r'^(TAX|GST|SST|CHANGE|CASH|VISA|MASTERCARD|DEBIT|CREDIT|PAYMENT|MYR)\b')
TAX_LABEL_RE = re.compile(
    r'\bTAX\s+(AMT|AMOUNT|TOTAL|TOTALS|CODE|RATE|SUMMARY)\b'
    r'|\bGST\s+(AMT|AMOUNT|SUMMARY|TOTAL|CODE|RATE|@)'
    r'|\bTAX\s+INVOICE\b'
)
SUMMARY_START_RE = re.compile(
    r'\bGST\s+SUMMARY\b|\bTAX\s+SUMMARY\b|\bTAX\s+CODE\b|\bGST\s+RATE\b'
)

TIER1 = re.compile(r'GRAND\s*TOTA')
TIER2 = re.compile(r'\bTOTAL\b[^A-Z\n]{0,3}\bRM\b')
TIER3 = re.compile(r'\bTOTAL\s+AMOUNT\b')
TIER4_PATTERNS = [
    re.compile(r'\bNETT?\s+TOTAL\b'),
    re.compile(r'\bTOTAL\s+DUE\b'),
    re.compile(r'\bAMOUNT\s+DUE\b'),
    re.compile(r'\bBALANCE\s+DUE\b'),
    re.compile(r'\bTOTAL\b'),
    re.compile(r'\bAMOUNT\b'),
]


def is_excluded(up_line):
    if EXCLUSION_RE.search(up_line):
        return True
    stripped = re.sub(r'^[^A-Z]*', '', up_line)
    if STRONG_EXCL_START.match(stripped):
        return True
    if TAX_LABEL_RE.search(up_line):
        return True
    return False


def find_summary_start(upper_lines):
    for i, l in enumerate(upper_lines):
        if SUMMARY_START_RE.search(l):
            return i
    return len(upper_lines)


def extract_total(text):
    lines = text.split('\n')
    upper_lines = [l.upper() for l in lines]
    stop = find_summary_start(upper_lines)

    def scan(pattern, loose=False, int_fallback=False):
        found = None
        for i in range(stop):
            up = upper_lines[i]
            if is_excluded(up):
                continue
            if pattern.search(up):
                amt = extract_amount(lines[i], loose=loose, int_fallback=int_fallback)
                if amt is None and i + 1 < len(lines):
                    nxt = upper_lines[i + 1]
                    if not is_excluded(nxt):
                        amt = extract_amount(lines[i + 1], loose=loose, int_fallback=int_fallback)
                if amt:
                    found = amt
        return found

    # Tier 1: try strict, then loose, then int fallback
    for kwargs in ({}, {'loose': True}, {'int_fallback': True}):
        r = scan(TIER1, **kwargs)
        if r:
            return r

    # Tier 2
    for kwargs in ({}, {'loose': True}):
        r = scan(TIER2, **kwargs)
        if r:
            return r

    # Tier 3
    r = scan(TIER3)
    if r:
        return r

    # Tier 4
    for pat in TIER4_PATTERNS:
        for kwargs in ({}, {'loose': True}):
            r = scan(pat, **kwargs)
            if r:
                return r
    return None


def process_image(path):
    variants = ocr_variants(path)
    dates = []
    totals = []
    for text in variants:
        dates.append(parse_date(text))
        totals.append(extract_total(text))

    def most_common_valid(vals):
        counts = {}
        for v in vals:
            if v is None:
                continue
            counts[v] = counts.get(v, 0) + 1
        if not counts:
            return None
        return max(counts.items(), key=lambda kv: (kv[1], vals.index(kv[0]) * -1))[0]

    date = most_common_valid(dates)
    total = most_common_valid(totals)
    return date, total


def main():
    files = sorted(f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png')))
    rows = []
    for f in files:
        date, total = process_image(os.path.join(IMG_DIR, f))
        rows.append((f, date, total))
        print(f, date, total)

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for r in rows:
        ws.append(list(r))
    wb.save(OUT)


if __name__ == "__main__":
    main()
